// Some portions generated by Claude
import { html, render, nothing } from './vendor/lit-html-3.3.3/lit-html.js';

// The Workbench views compile to ES5, where every evaluation of a tagged template creates a new strings array.
// Lit identifies a template by that array, so without this each render would rebuild the DOM it should update,
// losing typed text, focus and state set on elements. Reuse one array per distinct template text.
const templates = new Map();

function stable(strings) {
	const key = JSON.stringify(strings.raw || strings);
	const known = templates.get(key);
	if (known) {
		return known;
	}
	templates.set(key, strings);
	return strings;
}

window.RDF4JLitHTML = { html: (strings, ...values) => html(stable(strings), ...values), render, nothing };
